  function setURL(id,graph=null){const url=new URL(location.href);url.hash='research';for(const key of ['run','research','object_graph','graph_revision','step'])url.searchParams.delete(key);if(id)url.searchParams.set('research',id);else if(graph?.id){url.searchParams.set('object_graph',graph.id);if(Number.isInteger(graph.revision))url.searchParams.set('graph_revision',String(graph.revision));}if(url.href!==location.href)history.pushState(null,'',url);}
  function selectedCase(){return state.cases.find(x=>x.id===$('research-case').value);}
  function effectiveGraph(){if(state.purpose==='structure'&&!state.run)return{nodes:[],edges:[]};const selectedTransition=state.proofTransition;const run=selectedTransition&&state.run?.selected_transition_id&&state.run.selected_transition_id!==selectedTransition.id?null:state.run,c=selectedTransition?.case_id?state.cases.find(x=>x.id===selectedTransition.case_id):run?state.cases.find(x=>x.id===run.case_id):selectedCase();const target=selectedTransition?.agent_task?.target||run?.result?.fixture?.target||run?.plan?.target_id||c?.target;let nodes=run?list(run.nodes?.length?run.nodes:run.result?.nodes):list(c?.preview?.nodes||c?.nodes);let edges=run?list(run.edges?.length?run.edges:run.result?.edges):list(c?.preview?.edges||c?.edges);if(!run&&!nodes.length&&c?.preview_nodes){nodes=c.preview_nodes.map(id=>({id,label:id.split('.').pop(),kind:id===target?'target':/Quad$|Energy$|Form$/.test(id)?'definition':'lemma',status:'pending',statement:selectedTransition?.obligations?.find(o=>o.target===id)?.statement||(id===c?.target?c.expected_statement:undefined)}));edges=(c.preview_edges||[]).map(e=>({source:e[0],target:e[1],type:'planned_dependency'}));}nodes=nodes.map(n=>({...n,statement:selectedTransition?.obligations?.find(o=>o.target===n.id||o.target===n.target)?.statement||n.statement,kind:n.id===target?'target':n.kind==='def'?'definition':n.kind==='theorem'?'lemma':n.kind}));return window.ObjectGraphModel.proofSlice({nodes,edges},selectedTransition);}
