  function renderAvailability(data){state.availability=data;const codex=data.codex||{},lean=data.lean||{};const codexOK=codex.available===true||codex.ready===true||codex.status==='ready';const leanOK=lean.available===true||lean.ready===true||lean.status==='ready';const parts=[];if(data.engine)parts.push(typeof data.engine==='string'?data.engine:data.engine.name||'Контроллер подключён');parts.push(leanOK?'Lean готов':lean.available===false||lean.ready===false?'Lean недоступен':'Lean: проверка при запуске');parts.push(codexOK?'Astra / Codex доступен':codex.error||codex.reason||codex.message?'Codex: '+txt(codex.error||codex.reason||codex.message):'Codex: доступ определяется при запуске');$('research-connection').textContent=parts.join(' · ');$('research-connection').className='research-connection '+(codexOK?'available':'');}
  function renderHistory(){const box=$('research-history');box.replaceChildren();if(!state.runs.length){box.append(el('p',{class:'research-hint'},'Запуски сохраняются здесь вместе с результатами и попытками.'));return;}for(const run of state.runs){const b=el('button',{type:'button',class:'research-history-item'+(state.run?.id===run.id?' selected':''),'data-research-run':run.id});b.append(el('strong',{},run.title||run.case_id||'Исследование'));const meta=el('div',{class:'research-history-meta'});meta.append(status(['complete','completed'].includes(run.status)?run.outcome||run.result?.outcome||run.status:run.status),el('span',{},shortDate(run.created_at)),el('span',{},label(run.mode)));b.append(meta);b.onclick=()=>loadRun(run.id,true);box.append(b);}}
