    detail.append(el('p',{},'arXiv:'+paper.versioned_id+' · '+(paper.import_status==='ready'?'Снимок сохранён':paper.import_status||'Импортирован')));
    const provenance=el('details');provenance.append(el('summary',{},'Версия, хеш и ограничения источника'));
