  function paperQuestion(){const paper=state.paper;if(!paper)return '';const section=paper.sections?.find(s=>s.id===state.paperSection),scope=Array.isArray(state.paperSection)?', разделы '+state.paperSection.map(id=>paper.sections.find(s=>s.id===id)?.title||id).join('; '):section?', раздел «'+section.title+'»':'';return 'В статье «'+paper.title+'» (arXiv:'+paper.versioned_id+')'+scope+' выдели до шести конкретных переходов между математическими объектами. Для каждого сохрани точные условия, утверждение и ссылку на раздел. Отдели утверждения статьи от подготовленных Lean-постановок; не представляй частную модель как формализацию всей статьи.';}
