    onSelect(transition){state.proofTransition=transition;const graph=objectWorkspace.graph,key=graph?.id+':'+graph?.revision+':'+transition.id;if(!state.run&&graph?.id&&state.paperGraphSelection!==key){state.paperGraphSelection=key;restoreGraphPaper(graph,transition);}if((!transition.case_id||!transition.agent_task)&&$('research-mode').value==='pilot'){$('research-mode').value='single';updateMode();}},
